<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$rows=db()->query('SELECT c.id,c.status,c.last_message_at,o.order_number,o.customer_name,o.customer_nif FROM conversations c JOIN orders o ON o.id=c.order_id ORDER BY COALESCE(c.last_message_at,c.created_at) DESC LIMIT 300')->fetchAll();layout_start('Conversas');echo '<section class="panel"><h2>Conversas por pedido</h2><p class="hint">A interface de mensagens do cliente será ligada na próxima etapa. Aqui pode consultar as conversas existentes.</p><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>NIF</th><th>Última mensagem</th><th>Estado</th></tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="5" class="empty">Ainda não existem conversas.</td></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['order_number']).'</td><td>'.e($r['customer_name']).'</td><td>'.e($r['customer_nif']?:'—').'</td><td>'.e($r['last_message_at']?:'—').'</td><td><span class="badge">'.e($r['status']).'</span></td></tr>';echo '</tbody></table></div></section>';layout_end();
